  async function createCoinPackage(){
    if(!sb||!S.isAdmin)return;
    const name=$('#coinPackName')?.value.trim();
    const coins=Number($('#coinPackCoins')?.value||0);
    const price=Number(String($('#coinPackPrice')?.value||0).replace(',','.'));
    if(!name||coins<=0||price<=0)return alert('Informe nome, quantidade de Coins e preço maior que zero.');
    const {error}=await sb.from('coin_packages').insert({name,coins,price_cents:Math.round(price*100),active:true,sort_order:Number($('#coinPackOrder')?.value||0),created_by:S.user.id});
    if(error)alert(error.message);else{$('#coinPackageForm')?.reset();await loadAdminCoinPackages();await loadCoinPackages();render()}
  }
  async function editCoinPackage(id){
    if(!sb||!S.isAdmin)return;const x=(S.adminCoinPackages||[]).find(i=>i.id===id);if(!x)return;
    const name=prompt('Nome do pacote:',x.name);if(name===null)return;
    const coins=prompt('Quantidade de QuizCoins:',String(x.coins));if(coins===null)return;
    const price=prompt('Preço em reais (ex.: 10.00):',String((Number(x.price_cents||0)/100).toFixed(2)));if(price===null)return;
    const active=confirm('Deixar este pacote ativo?');
    const {error}=await sb.from('coin_packages').update({name:name.trim(),coins:Number(coins),price_cents:Math.round(Number(String(price).replace(',','.'))*100),active}).eq('id',id);
    if(error)alert(error.message);else{await loadAdminCoinPackages();await loadCoinPackages();render()}
  }
  async function createCoinPayment(packageId){
    if(!sb||!S.user)return alert('Faça login para comprar QuizCoins.');
    return alert('A compra de QuizCoins com Mercado Pago está desativada no momento. As Coins gratuitas continuam disponíveis nas partidas.');
    const btn=document.querySelector(`[data-coin-package="${CSS.escape(String(packageId))}"]`);if(btn)btn.disabled=true;
    try{
      const {data,error}=await sb.functions.invoke('create-coin-payment',{body:{coin_package_id:packageId}});
      if(error)throw error;
      if(!data?.checkout_url)throw new Error(data?.error||data?.message||'O Mercado Pago não retornou o checkout.');
      window.location.href=data.checkout_url;
    }catch(err){alert(err?.message||'Não foi possível iniciar o pagamento.');if(btn)btn.disabled=false;}
  }
