  async function loadAdminAccounts(){
    if(!sb||!S.isAdmin)return;
    S.adminAccountsLoaded=false; S.adminAccountsError='';
    const {data,error}=await sb.rpc('admin_list_accounts');
    if(!error){
      S.adminAccounts=Array.isArray(data)?data:[];
      S.adminAccountsLoaded=true;
      render();
      return;
    }
    console.warn('admin_list_accounts',error.message);
    S.adminAccountsError=error.message||'Não foi possível carregar as contas.';
    // Fallback: tenta ao menos carregar os perfis visíveis. A RPC continua sendo
    // a fonte oficial porque ela também consegue trazer o e-mail do Auth.
    const fallback=await sb.from('profiles').select('id,username,display_name,role').order('username',{ascending:true}).limit(500);
    if(!fallback.error){
      S.adminAccounts=(fallback.data||[]).map(x=>({...x,email:'',created_at:null}));
      S.adminAccountsLoaded=true;
    }
    render();
  }
