  async function loadNotifications(){if(!sb||!S.user)return;const {data,error}=await sb.from('notifications').select('id,recipient_id,actor_id,type,title,body,data,read_at,created_at').eq('recipient_id',S.user.id).order('created_at',{ascending:false}).limit(50);if(error){console.error(error);return}S.notifications=data||[];S.notificationUnread=S.notifications.filter(n=>!n.read_at).length;const ids=[...new Set(S.notifications.map(n=>n.actor_id).filter(Boolean))];if(ids.length){const {data:pdata}=await sb.from('profiles').select('id,username,display_name,avatar_url,xp,level,wins,losses,draws,premium_vip,premium_frame,premium_effect,premium_theme,premium_avatar,premium_title,premium_badge').in('id',ids);S.notificationActors={};(pdata||[]).forEach(p=>S.notificationActors[p.id]=p)}S.notificationsLoaded=true}
  function subscribeNotifications(){if(!sb||!S.user)return;if(S.notificationRealtime)sb.removeChannel(S.notificationRealtime);S.notificationRealtime=sb.channel(`notifications-${S.user.id}`).on('postgres_changes',{event:'INSERT',schema:'public',table:'notifications',filter:`recipient_id=eq.${S.user.id}`},async payload=>{const n=payload.new;if(!S.notifications.some(x=>x.id===n.id)){S.notifications.unshift(n);S.notificationUnread++;const actorId=n.actor_id;if(actorId){const {data:p}=await sb.from('profiles').select('id,username,display_name,avatar_url,premium_vip,premium_frame,premium_effect,premium_theme,premium_avatar,premium_title,premium_badge').eq('id',actorId).maybeSingle();if(p)S.notificationActors[p.id]=p}sound('click');render()}}).on('postgres_changes',{event:'UPDATE',schema:'public',table:'notifications',filter:`recipient_id=eq.${S.user.id}`},payload=>{const i=S.notifications.findIndex(x=>x.id===payload.new.id);if(i>=0){S.notifications[i]=payload.new;S.notificationUnread=S.notifications.filter(n=>!n.read_at).length;render()}}).subscribe()}
