  async function loadPremiumInventory(){
    if(!sb||!S.user)return;
    const {data,error}=await sb.from('user_premium_items').select('item_id,active,purchased_at').eq('user_id',S.user.id);
    if(error){console.warn('premium inventory',error.message);return;}
    const ids=(data||[]).map(x=>x.item_id).filter(Boolean);
    let items=[];
    if(ids.length){const {data:rows}=await sb.from('premium_items').select('id,name,category,description,price_coins,price_cents,promo_price_coins,promo_price_cents,promo_active,promo_expires_at,icon,asset_url,asset_type,effect_style,kind,source_type,source_id,active').in('id',ids);items=rows||[];}
    S.inventoryItems=(data||[]).map(row=>{const x=items.find(i=>i.id===row.item_id);if(!x)return null;return {...x,price:Number(x.price_coins??x.price_cents??0),asset_type:x.asset_type||'',effect_style:x.effect_style||'none',source_type:x.source_type||'',source_id:x.source_id||'',promo_price:Number(x.promo_price_coins??x.promo_price_cents??0),cat:x.category,desc:x.description||'',activeOwned:!!row.active,kind:x.kind||({Molduras:'frame',Efeitos:'effect',Títulos:'title',Emojis:'emoji',Avatares:'avatar','Fundos de Perfil':'background',Temas:'theme',Badges:'badge',Emblemas:'badge'}[x.category]||'theme'),purchased_at:row.purchased_at||null};}).filter(Boolean);
    S.premium.owned=[...new Set([...(S.premium.owned||[]),...S.inventoryItems.map(x=>x.id)])];
    const activeByKind={};S.inventoryItems.filter(x=>x.activeOwned).forEach(x=>{if(x.kind)activeByKind[x.kind]=x.id});
    S.premium.active={...activeByKind,...S.premium.active};
  }
  async function useInventoryItem(id){
    const item=S.inventoryItems.find(x=>x.id===id);if(!item||!sb)return;
    if(item.activeOwned){
      const {error}=await sb.from('user_premium_items').update({active:false}).eq('user_id',S.user.id).eq('item_id',id);
      if(error)return alert(error.message||'Não foi possível desativar o item.');
      const next={...(S.premium.active||{})};delete next[item.kind];S.premium.active=next;
    }else{
      const {error}=await sb.rpc('activate_premium_item',{p_item_id:id});
      if(error)return alert(error.message||'Não foi possível ativar o item.');
      S.premium.active={...S.premium.active,[item.kind]:item.id};
      if(item.kind==='title')await loadUserTitles(S.user.id);
      if(item.kind==='vip')S.premium.owned=[...new Set([...(S.premium.owned||[]),'vip'])];
    }
    premiumSave();await persistPremiumProfile();await loadPremiumInventory();render();
  }
  async function loadProfile(){
    if(!sb||!S.user)return;
    let {data,error}=await sb.from('profiles').select('id,username,display_name,avatar_url,xp,level,wins,losses,streak,role,coins,main_title_id,premium_vip,premium_frame,premium_effect,premium_theme,premium_background,premium_avatar,premium_title,premium_badge').eq('id',S.user.id).single();
    if(error){const fallback=await sb.from('profiles').select('id,username,display_name,avatar_url,xp,level,wins,losses,streak,role').eq('id',S.user.id).single();data=fallback.data;error=fallback.error;}
    S.profile=data||{username:S.user.email?.split('@')[0],display_name:S.user.email?.split('@')[0],coins:0};premiumLoad();S.premium.coins=Number(S.profile?.coins??S.premium.coins??0);await loadPremiumInventory();
    if(S.profile?.premium_frame||S.profile?.premium_title||S.profile?.premium_effect||S.profile?.premium_theme||S.profile?.premium_background||S.profile?.premium_avatar){S.premium.active={...S.premium.active,frame:S.profile.premium_frame||S.premium.active.frame,title:S.profile.premium_title||S.premium.active.title,effect:S.profile.premium_effect||S.premium.active.effect,theme:S.profile.premium_theme||S.premium.active.theme,background:S.profile.premium_background||S.premium.active.background,avatar:S.profile.premium_avatar||S.premium.active.avatar,badge:S.profile.premium_badge||S.premium.active.badge};premiumSave();}
    await loadUserTitles(S.user.id);S.isAdmin=S.profile.role==='admin';
  }
