  function support(){const rows=S.supportRows||[];return `<section class="support-page"><div class="title">💬 Suporte</div><p class="subtitle">Fale com a equipe do QuizUp. Você pode sair do aplicativo e voltar sem perder a conversa.</p><div class="card pad"><div id="supportMessages" class="support-messages">${rows.length?rows.map(m=>`<div class="support-msg ${m.sender_id===S.user.id?'mine':''}"><div>${esc(m.message)}</div><small>${new Date(m.created_at).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})}</small></div>`).join(''):'<div class="muted center">Nenhuma mensagem ainda. Como podemos ajudar?</div>'}</div><form id="supportForm" class="chat-compose support-compose"><textarea id="supportInput" maxlength="1000" required rows="3" placeholder="Digite sua mensagem..."></textarea><button class="send-chat" type="submit">➤</button></form></div><button class="secondary" id="supportHome">← VOLTAR</button></section>`} 
  async function loadSupport(){if(!sb||!S.user)return;let {data:thread,error}=await sb.from('support_threads').select('id,status').eq('user_id',S.user.id).order('created_at',{ascending:false}).limit(1).maybeSingle();if(error)return console.warn(error);if(!thread){const r=await sb.from('support_threads').insert({user_id:S.user.id}).select('id,status').single();if(r.error)return console.warn(r.error);thread=r.data}S.supportThread=thread;const r=await sb.from('support_messages').select('id,thread_id,sender_id,message,created_at').eq('thread_id',thread.id).order('created_at',{ascending:true});if(!r.error)S.supportRows=r.data||[];if(S.realtime)sb.removeChannel(S.realtime);S.realtime=sb.channel('support-'+thread.id).on('postgres_changes',{event:'INSERT',schema:'public',table:'support_messages',filter:`thread_id=eq.${thread.id}`},payload=>{if(!S.supportRows.some(x=>x.id===payload.new.id)){S.supportRows.push(payload.new);if(S.route==='support')render()}}).subscribe();if(S.route==='support')render()}
