  async function sendMatchReaction(emoji){if(!sb||!S.matchId||!S.user||!emoji)return;S.emojiOpen=false;const reaction={id:`local-${Date.now()}-${Math.random().toString(36).slice(2,7)}`,match_id:S.matchId,sender_id:S.user.id,emoji,created_at:new Date().toISOString()};if(Date.now()-(S.lastReactionAt||0)<350)return;S.lastReactionAt=Date.now();if(!S.matchReactions.some(x=>x.sender_id===S.user.id&&x.emoji===emoji&&Date.now()-new Date(x.created_at).getTime()<1000)){S.matchReactions.push(reaction);if(S.matchReactions.length>10)S.matchReactions.shift();S.lastReaction=emoji;render();}const {error}=await sb.from('match_reactions').insert({match_id:S.matchId,sender_id:S.user.id,emoji});if(error)console.warn('reaction',error.message);setTimeout(()=>{S.lastReaction='';render()},1800)}
